using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ── CalculateTotal: DataRow-driven tests ──────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0, 50.00, DisplayName = "Multiple items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00, DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62, DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00, 10, 0.10, 0.00, DisplayName = "Zero unit price")]
    [DataRow(10.00, 0, 0.10, 0.00, DisplayName = "Zero quantity")]
    [DataRow(99.99, 1, 1.0, 199.98, DisplayName = "Maximum tax rate (100%)")]
    public void CalculateTotal_ValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    // ── CalculateTotal: exception cases via DataRow ───────────────────

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, "unitPrice", DisplayName = "Negative unit price")]
    [DataRow(10.00, -1, 0.10, "quantity", DisplayName = "Negative quantity")]
    [DataRow(10.00, 1, -0.01, "taxRate", DisplayName = "Negative tax rate")]
    [DataRow(10.00, 1, 1.01, "taxRate", DisplayName = "Tax rate above 1")]
    public void CalculateTotal_InvalidInputs_ThrowsArgumentOutOfRange(
        double unitPrice, int quantity, double taxRate, string expectedParam)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual(expectedParam, ex.ParamName);
    }

    // ── ApplyDiscount: DynamicData with test-case objects ─────────────

    public record DiscountCase(decimal Price, decimal DiscountPercent, decimal Expected);

    private static IEnumerable<object[]> DiscountCases()
    {
        yield return [new DiscountCase(100m, 0m, 100m)];    // no discount
        yield return [new DiscountCase(100m, 10m, 90m)];     // 10%
        yield return [new DiscountCase(100m, 50m, 50m)];     // 50%
        yield return [new DiscountCase(100m, 100m, 0m)];     // full discount
        yield return [new DiscountCase(59.99m, 25m, 44.9925m)]; // fractional result
        yield return [new DiscountCase(0m, 50m, 0m)];        // zero price
    }

    [TestMethod]
    [DynamicData(nameof(DiscountCases), DynamicDataSourceType.Method)]
    public void ApplyDiscount_ValidInputs_ReturnsExpected(DiscountCase tc)
    {
        var result = _calculator.ApplyDiscount(tc.Price, tc.DiscountPercent);

        Assert.AreEqual(tc.Expected, result);
    }

    // ── ApplyDiscount: boundary / exception cases ─────────────────────

    [TestMethod]
    [DataRow(-0.01, DisplayName = "Discount below 0%")]
    [DataRow(100.01, DisplayName = "Discount above 100%")]
    public void ApplyDiscount_InvalidDiscount_ThrowsArgumentOutOfRange(double discount)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, (decimal)discount));
    }

    // ── FormatPrice: DataRow-driven tests ─────────────────────────────

    [TestMethod]
    [DataRow(9.99, "$", "$9.99", DisplayName = "Default symbol")]
    [DataRow(1234.5, "€", "€1234.50", DisplayName = "Euro symbol, rounds to 2dp")]
    [DataRow(0.0, "£", "£0.00", DisplayName = "Zero price")]
    public void FormatPrice_ReturnsFormattedString(
        double price, string symbol, string expected)
    {
        var result = _calculator.FormatPrice((decimal)price, symbol);

        Assert.AreEqual(expected, result);
    }
}

